import pandas as pd
import numpy as np

def calculate_indicators(data):
    data['ATR'] = data['High'].rolling(window=14).apply(lambda x: np.mean([abs(x[i] - x[i-1]) for i in range(1, len(x))]))
    data['ADX'] = data['High'].rolling(window=14).apply(lambda x: np.mean([abs(x[i] - x[i-1]) / x[i-1] for i in range(1, len(x))]))
    data['Bollinger_Bands_Upper'] = data['Close'].rolling(window=20).mean() + 2 * data['Close'].rolling(window=20).std()
    data['Bollinger_Bands_Lower'] = data['Close'].rolling(window=20).mean() - 2 * data['Close'].rolling(window=20).std()
    data['Volume_Profile'] = data['Volume'].rolling(window=20).mean()

def generate_signals(data):
    signals = pd.DataFrame(index=data.index)
    signals['long'] = False
    signals['short'] = False

    for i in range(len(data)):
        if data['Close'].iloc[i] > data['Bollinger_Bands_Upper'].iloc[i] and data['ADX'].iloc[i] > 25 and data['ATR'].iloc[i] > data['ATR'].rolling(window=5).mean().iloc[i]:
            signals['long'].iloc[i] = True
        elif data['Close'].iloc[i] < data['Bollinger_Bands_Lower'].iloc[i] and data['ADX'].iloc[i] > 25 and data['ATR'].iloc[i] > data['ATR'].rolling(window=5).mean().iloc[i]:
            signals['short'].iloc[i] = True

    return signals

def calculate_stop_loss_trailing(data, signals):
    stop_loss_trailing = pd.DataFrame(index=data.index)
    stop_loss_trailing['long'] = np.nan
    stop_loss_trailing['short'] = np.nan

    for i in range(len(data)):
        if signals['long'].iloc[i]:
            stop_loss_trailing['long'].iloc[i] = data['Close'].iloc[i] * (1 - 0.05)
        elif signals['short'].iloc[i]:
            stop_loss_trailing['short'].iloc[i] = data['Close'].iloc[i] * (1 + 0.05)

    return stop_loss_trailing

def calculate_position_sizing(data, signals):
    position_sizing = pd.DataFrame(index=data.index)
    position_sizing['long'] = 0
    position_sizing['short'] = 0

    for i in range(len(data)):
        if signals['long'].iloc[i]:
            position_sizing['long'].iloc[i] = 0.02
        elif signals['short'].iloc[i]:
            position_sizing['short'].iloc[i] = 0.02

    return position_sizing

